CREATE TABLE sales (id INTEGER, product TEXT, amount INTEGER);
INSERT INTO sales VALUES (1, 'Widget', 100), (2, 'Widget', 150), (3, 'Gadget', 200), (4, 'Gadget', 120);
WITH product_totals AS (SELECT product, SUM(amount) as total FROM sales GROUP BY product) SELECT product, total FROM product_totals WHERE total > 200 ORDER BY product;
